### Problem Description

After upgrading from ES `8.6.2` to `8.7.1` I noticed that `params['_source']` value is wrong sometimes when it's accessed in `runtime_mappings` field's script as in:

```
"runtime_mappings": {
  "runtime_field": {
    "type": "keyword",
    "script": {
      "lang": "painless",
      "source": "emit(params['_source'].toString())"
    }
  }
}
```



### Steps to Reproduce

```
PUT foo_bar
{
  "mappings": {
    "properties": {
      "id": {
        "type": "text"
      },
      "name": {
        "type": "text",
        "fields": {
          "raw": {
            "type": "keyword"
          }
        }
      }
    }
  },
  "settings": {
    "index": {
      "number_of_shards": 3,
      "number_of_replicas": 2
    }
  }
}

POST foo_bar/_bulk?refresh=true
{"index":{}}
{"id":"1","name":"name 1"}
{"index":{}}
{"id":"2","name":"name 2"}
{"index":{}}
{"id":"3","name":"name 3"}
{"index":{}}

GET foo_bar/_search
{
  "size": 0,
  "runtime_mappings": {
    "runtime_field": {
      "type": "keyword",
      "script": {
        "lang": "painless",
        "source": "emit(params['_source'].toString())"
      }
    }
  },
  "fields": [
    "runtime_field"
  ],
  "aggs": {
    "aggregation": {
      "terms": {
        "field": "name.raw"
      },
      "aggs": {
        "hits": {
          "top_hits": {
            "_source": true
          }
        }
      }
    }
  },
  "from": 0
}

```

